INSERT INTO `banner` VALUES (39,'Electronic  and Accesories',NULL,NULL,NULL,NULL,0,NULL,'boat-stone-uno-3w-bluetooth-speaker',NULL,NULL,'<ul><li>Electronics and accessories include a wide range of devices—such as smartphones, laptops, and smart wearables—paired with supplementary products like chargers, cases, and cables that improve functionality, protection, and user experience.&nbsp;</li><li>These essential add-ons (headphones, power banks, screen protectors) enable data transfer, power management, and portability.&nbsp;</li></ul>','2',1,'2026-02-09 13:19:08','2026-02-10 06:45:48',NULL,NULL,2),(41,'best seler',NULL,NULL,NULL,NULL,0,NULL,'audio-equipment1',NULL,NULL,'','1',1,'2026-02-10 06:43:44',NULL,NULL,NULL,3),(42,'fashion',NULL,NULL,NULL,NULL,0,NULL,'clothes1',NULL,NULL,'','3',1,'2026-02-10 06:44:44',NULL,NULL,NULL,3),(43,'Beauty and Skincare related Banner',NULL,NULL,NULL,NULL,0,NULL,'beauty-products1',NULL,NULL,'','4',1,'2026-02-10 06:51:12','2026-02-10 07:02:50',NULL,NULL,3);
