INSERT INTO `email_template` VALUES (1,'Register Content','Registration Successfully','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                \n		Thank you for expressing your interest and registering with <b> {storeName}</b>,your gateway to a smarter eCommerce experience.<br>\n		 We look forward to providing you with an exceptional shopping experience.<br>\n\n                </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name}'),(2,'Forgot Password Content','Forgot Password','Dear {name},<br/><br/>        <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px\'> Your new Password is :  {xxxxxx}  </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{xxxxxx}'),(3,'Contact Content','A new enquiry through \'Contact Us\'','<p>Dear Admin,</p><br/><br/>        \n            <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px\'>\n             You have received a new enquiry. Here are the details: <br> Details: </p><br>\n             <p><b>Name :</b> {name},<br>\n             <b>bEmail:</b> {email}, <br>\n             <b>Phone Number :</b> {phoneNumber}, <br>\n             <b>Message :<>/b {message}.  </p><br>\n             <p>Please review and respond as necessary.</p>',1,'2023-11-23 13:36:30','2024-09-16 12:50:39',NULL,NULL,'{name},{phoneNumber},{email},{message}'),(4,'Create Customer Content','Customer Login created successfully','Dear {name},<br><br>\n            <p>We are pleased to inform you that you have been added as a customer at <b>{storeName}</b>. Here are your login credentials: </p><br>             \n              <p><b>User ID :</b> {username}<br>\n              <b>Password :</b> {password}</p> <br>\n              <p> You can log in using the above credentials.\nWishing you the best eCommerce experience with <b>{storeName}</b>. </p>',1,'2023-11-23 13:36:30','2024-09-16 10:49:17',NULL,NULL,'{name},{storeName},{username},{password}'),(5,'Customer Order Content','Details of your recent Order','<h1\n                                                                                        style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                                                                                        Hi {name},</h1>\n                                                                                    <p\n                                                                                        style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\n                                                                                        You have successfully placed an order. Kindly find the following details on the placed order.</p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name}'),(6,'Admin Mail Content','Congratulations on your recent order','<h1\n                                                                                        style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                                                                                        Hi {adminname},</h1>\n                                                                                    <p\n                                                                                        style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\n                                                                                        A New Order <b>{orderId}</b> from the Customer <b>{name}</b> has been successfully placed. Please find the following details of the placed order below.</p>',1,'2023-11-23 13:36:30','2024-09-16 11:41:55',NULL,NULL,'{adminname},{orderId},{name}'),(7,'Create admin user Content','Login Credentials for Additional Admin User','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1><br>\n                \n<p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We are pleased to inform you that you have been added as an admin user in <b>{storeName}</b>. Here are your login credentials:<br><br>\n<b>User ID :</b> {username}<br>\n<b>Password :</b> {password}<br><br>\nYou can log in using the above credentials and begin your journey as an \'Additional Admin User\' at <b>{storeName}.</b></p><br>',1,'2023-11-23 13:36:30','2024-09-16 12:00:42',NULL,NULL,'{name},{storeName},{username},{password},{storeName}'),(9,'Oauth register mail','Oauth register mail','Dear {name},<br/><br/><p style=\"margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px;\">Thank you for showing your interest in SpurtCommerce, your temporary password for next time login is: {xxxxxx} or you can login through Oauth</p>',1,'2019-08-08 00:00:00','2019-08-08 18:45:15',NULL,NULL,NULL),(11,'vendor Registration','Congratulations, Now you can login to your Seller Panel','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1><br><br>\n                \n<p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We\'re glad to inform you that you are now a registered Seller on <b>{siteName}.</b><br><br>\n                In your Seller Panel, now you can begin with creating a Seller Profile and submitting the documents for verification, to become a ‘Verified Seller’.<br><br>\n                Should you face any problems in filling the profile details or submitting the documents, feel free to contact our support team at <a href=<b>{siteUrl}.</b>></a><br><br>\n                We will be more than happy to assist you. <br> \n		Wish you a wonderful Journey as a Seller on <b>{siteName}.</b><br>\n                </p><br>\n',1,'2023-11-23 13:36:30','2024-09-14 16:08:47',NULL,NULL,'{name},{storeName}'),(12,'admin notification for vendor registration','New Seller Registration Completed: {sellerName}\n','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1><br><br>\n                \n<p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We are pleased to inform you that <b>{sellerName}</b> has successfully registered as a Seller on <b>{siteName}</b><br>.\n                The Seller Panel has been activated, and the seller can now create their profile and submit documents for verification to become a \'Verified Seller.\'<br><br>\n                \n                Please monitor their profile completion and document submission for the verification process.<br>\n                If any issues arise during this process, kindly offer assistance or notify the support team to resolve them.<br><br>\n                \n                Let us ensure the seller’s experience on <b>{siteName}</b> is smooth and successful.<br>\n                </p><br>\n',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{vendorName}'),(13,'vendor creation','vendor creation','Dear {name},<br/><br/>    We are glad to inform you that Spurtcommerce  has added you as Vendor.Here are your User Credentials for logging into the Application <br>     <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;\'>  User ID : {username}</p>        <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;\'>  Password : {password}</p> <br/>        <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px\'> You may login using the above Email Id and Password. </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{username},{password}'),(15,'vendor login Request','Congratulations, Now you are an Approved Seller on {siteName} ','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600; margin: 0 0 12px 0; color: #1F2328;\">\n        Hi {name},\n    </h1><br><br>\n\n    <p\n    style=\"font-size: 16px; line-height: 24px; color: #1F2328; font-weight: normal; margin: 0 0 24px 0;\">\n    We are glad to inform you that you are now an Approved Seller on <b>{siteName}.</b><br><br>\n    In your Seller Panel, now you can start adding products and start your selling business at <b>{siteName}.</b><br><br>\n    Should you face any problems in adding products or using the SpurtCart Seller Panel, please feel free to contact our support team at\n    <a href=\"{supportUrl}\"><b>{supportUrl}</b></a>.\n    We will be more than happy to assist you.<br><br>\n    Alternatively, you may use the chat option on your dashboard to directly message the Admin in case of any urgent assistance required.<br>\n    Wish you a wonderful Journey as a Seller on <b>{siteName}.</b>\n    </p><br><br>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{link}'),(16,'product approval mail','Product Approval Notification','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We are excited to inform you that your product, <b>{productname}</b>, has been successfully reviewed and approved for listing on <b>{siteName}!</b>.<br><br>\n                Your product is now live and available for customers to view and purchase on the platform.<br> You can manage your product details, inventory, and sales through your Seller Panel at any time.<br><br>\n                \n                If you have any questions or need assistance, feel free to reach out to our support team at <b><a href={siteUrl}></a>.</b><br><br>\n                Wishing you great success in selling on <b>{siteName}.</b>\n               <br>\n                </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{productname},{siteName}'),(17,'Email posting question','Product Question Alert','<h1\n                                                                                    style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                                                                                    Hi {name},</h1>\n                                                                                <p\n                                                                                    style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\n                                                                                    A Customer has just posted a question for the product.</p>\n                                                                            </td>\n                                                                        </tr>\n\n\n\n                                                                        <tr>\n                                                                            <td>\n\n                                                                                <table width=\" 100%\" cellpadding=\"0\"\n                                                                                    cellspacing=\"0\" role=\"presentation\">\n                                                                                    <tbody>\n                                                                                        <tr>\n\n                                                                                            <td>\n                                                                                                <table width=\" 100%\"\n                                                                                                    cellpadding=\"0\"\n                                                                                                    cellspacing=\"0\"\n                                                                                                    role=\"presentation\">\n                                                                                                    <tbody>\n                                                                                                        <tr>\n                                                                                                            <td\n                                                                                                                style=\"border-width:1px 0 0 0 ; border-style: solid; border-color: #D8DEE3; padding: 16px 0;\">\n                                                                                                                <img width=\"93\"\n                                                                                                                   height=\"93\" src=\"{productUrl}\"\n                                                                                                                    alt=\"product\">\n                                                                                                            </td>\n                                                                                                            <td class=\"product-detail\"\n                                                                                                                style=\"padding:16px 40px 16px 10px; border-width:1px 0 0 0 ; border-style: solid; border-color: #D8DEE3;\">\n                                                                                                                <h4\n                                                                                                                    style=\"color: #262626;font-size: 14px;line-height: 18px;font-weight: normal;margin: 0 0 8px 0;\">\n                                                                                                                    {title}\n                                                                                                                </h4>\n                                                                                                                <h5\n                                                                                                                    style=\"font-size: 14px;line-height: 17px;font-weight: 600;color: #262626;margin:0 ;\">\n                                                                                                                    {price}\n                                                                                                                </h5>\n\n                                                                                                            </td>\n\n                                                                                                        </tr>\n\n\n                                                                                                    </tbody>\n                                                                                                </table>\n                                                                                            </td>\n\n                                                                                        </tr>\n                                                                                    </tbody>\n                                                                                </table>\n                                                                            </td>\n                                                                        </tr>\n                                                                        <tr>\n                                                                            <td\n                                                                                style=\"padding: 24px 16px; background-color: #F9F9FC;\">\n                                                                                <p\n                                                                                    style=\"margin:0  0 16px 0 ; font-size: 14px;font-weight: normal; line-height: 24px; color: #262626;\">\n                                                                                    Question</p>\n                                                                                <h2\n                                                                                    style=\"color: #262626;font-size: 18px;line-height: 26px;font-weight: 600;margin:0 0 12px 0;\">\n                                                                                    {question}</h2>\n                                                                            </td>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{title},{question},{username}'),(18,'Email posting answer','Product Answer notification','<table width=\" 100%\" cellpadding=\"0\" cellspacing=\"0\"\n                                                                    role=\"presentation\">\n                                                                    <tbody>\n                                                                        <tr>\n                                                                            <td>\n                                                                                <h1\n                                                                                    style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                                                                                    Hi {name},</h1>\n                                                                                <p\n                                                                                    style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\n                                                                                    {replier} just answered to the question that you posted for the product</p>\n                                                                            </td>\n                                                                        </tr>\n\n\n\n                                                                        <tr>\n                                                                            <td>\n\n                                                                                <table width=\" 100%\" cellpadding=\"0\"\n                                                                                    cellspacing=\"0\" role=\"presentation\">\n                                                                                    <tbody>\n                                                                                        <tr>\n\n                                                                                            <td>\n                                                                                                <table width=\" 100%\"\n                                                                                                    cellpadding=\"0\"\n                                                                                                    cellspacing=\"0\"\n                                                                                                    role=\"presentation\">\n                                                                                                    <tbody>\n                                                                                                        <tr>\n                                                                                                            <td\n                                                                                                                style=\"border-width:1px 0 0 0 ; border-style: solid; border-color: #D8DEE3; padding: 16px 0;\">\n                                                                                                                <img width=\"93\"\n                                                                                                                   height=\"93\" src=\"{productUrl}\"\n                                                                                                                    alt=\"product\">\n                                                                                                            </td>\n                                                                                                            <td class=\"product-detail\"\n                                                                                                                style=\"padding:16px 40px 16px 10px; border-width:1px 0 0 0 ; border-style: solid; border-color: #D8DEE3;\">\n                                                                                                                <h4\n                                                                                                                    style=\"color: #262626;font-size: 14px;line-height: 18px;font-weight: normal;margin: 0 0 8px 0;\">\n                                                                                                                    {title}\n                                                                                                                </h4>\n                                                                                                                <h5\n                                                                                                                    style=\"font-size: 14px;line-height: 17px;font-weight: 600;color: #262626;margin:0 ;\">\n                                                                                                                    {price}\n                                                                                                                </h5>\n\n                                                                                                            </td>\n\n                                                                                                        </tr>\n\n\n                                                                                                    </tbody>\n                                                                                                </table>\n                                                                                            </td>\n\n                                                                                        </tr>\n                                                                                    </tbody>\n                                                                                </table>\n                                                                            </td>\n                                                                        </tr>\n                                                                        <tr>\n                                                                            <td\n                                                                                style=\"padding: 24px 16px; background-color: #F9F9FC;\">\n                                                                                <p\n                                                                                    style=\"margin:0  0 16px 0 ; font-size: 14px;font-weight: normal; line-height: 24px; color: #262626;\">\n                                                                                    Question & Answer</p>\n                                                                                <h2\n                                                                                    style=\"color: #262626;font-size: 18px;line-height: 26px;font-weight: 600;margin:0 0 12px 0;\">\n                                                                                    {question}</h2>\n                                                                                <p\n                                                                                    style=\"font-size: 14px;line-height: 24px;color: #262626;font-weight: normal; margin: 0;\">\n                                                                                    {answer}</p>\n                                                                            </td>\n\n                                                                        </tr>\n                                                                    </tbody>\n                                                                </table>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{title},{question},{answer},{username}'),(19,'Report Abuse','Report Abuse','<p>Dear {name},<br />&nbsp;</p><p>{username} posted Report Abuse for your product <u>{title}</u>,<br></p><p><i>Question</i> : {question}</p></p><p><i>Answer</i> : {answer}</p><br>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{username},{title},{question},{answer}'),(20,'updated cancel request status','Updation mail for your cancel order request','Dear {name},<br/><br/> <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px\'> Your request for cancelling ordered product: {productname} is {status} by seller.   </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{productname},{status}'),(21,'order status change update',' Order Status change update','Hello {name},<br/><br/> <p style=\'margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px\'> Here is a new update on your recent order on \'Spurt Cart\'.\nThe status of the product {title} in the order number {order} is -  \'{status}\' \nYou can view the complete details of your Order status, in the \'My Order History\' section of your Customer Account at Spurt Cart. </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{title},{order},{status}'),(22,'Quotation Request Mail','Product Quotation Request','<p> Dear {name}, </p> <br/><br/><p style= margin-bottom:.5em; margin: 0 0 10px 0;text-indent: 50px> Here is a new Quotation for your product {title} from customer -{customername}. </p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{title},{customername}'),(23,'Forgot password link','Forgot password link','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                \n		We\'ve received a request to change your login password. To proceed, please Click The Below Link for reset your password.<br><br>\n		 <b><a href= {link} style=\"display: block;\n    text-decoration: none;\n    padding: 16px 40px;\n    background-color: #027600;\n    border-radius: 6px;\n    color: #FFFFFF;\n    font-size: 16px;\n    line-height: 20px;\n    width: fit-content;\n    margin: auto;\">Click Here</a></b><br></p>',1,'2023-11-23 13:36:30','2024-06-18 04:39:14',NULL,NULL,'{name},{link}'),(24,'Invoice mail','Invoice mail','<p>Dear {name},<br />\n&nbsp;</p>\n\n<p>Here is an invoice attachment for this purchased order - {orderPrefixId}.</p>\n',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{orderPrefixId}'),(25,'Otp Verification','otp send successsfully','<p>Dear {name},<br />&nbsp;</p><p>{message}</p>',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name},{message}'),(30,'Abandoned Cart Content','Spurt Cart - hey, you have forgotten the items in your Cart !!!','Dear {name},\n\n                <p>We noticed that you recently visited our online store and added some items to your shopping cart. But, it seems like you haven\'t completed your purchase yet. We wanted to remind you on what you left behind and offer some assistance.</p>\n\n                <p>Here\'s your cart details:</p>\n\n                {cartDetail}\n\n                <p>If you have any questions about the products, need assistance with the checkout process, or require more information, our customer support team is here to help. Feel free to reach out to us via email at {supportEmail} or call us directly at {supportNumber}. We will be happy to provide any assistance.</p>\n\n                <p>Click on the following link to return to your shopping cart and complete your purchase.</p>\n\n                <p>Thank you for shopping with us !!!<p>\n\n                <p>Regards,</p>\n                {storeName}',1,'2023-11-23 13:36:30','2023-11-23 13:36:30',NULL,NULL,'{name}'),(31,'otp','Your OTP for email verification at {siteName}','     <h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi there,\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                Appreciate your first step towards becoming a \'{type}\' on <b>{appName}</b>.<br><br>\n\n		In order to get started, verify your email with the OTP.<br><br>\n		Use the following one-time password (OTP) to get your email verified and start registering as a \'{type}\' on <b>{siteName}</b>.  This OTP will only be valid for {duration} hours.<br><br>\n                </p>\n            <h2\n                style=\"font-size: 22px; font-weight: bold;line-height: 26px;color: #1F2328;margin: 0 0 32px 0;\"> {3}\n            </h2><br>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 26px 0;\">\n		If you did not make this request, just ignore the email and we will forget this ever happened. \n\n                </p>\n        ',1,'2024-05-15 13:57:33','2024-05-15 13:57:33',NULL,NULL,'{name}, {appName}, {duration}, {durationDetail}, {otp}, {appName}'),(32,'customer_register','Welcome to {storeName}! Your Regisration is successful','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                \n		Thank you for expressing your interest and registering with <b> {storeName}</b>,your gateway to a smarter eCommerce experience.<br>\n		 We look forward to providing you with an exceptional shopping experience.<br>\n\n                </p>',1,'2024-05-16 16:20:57','2024-09-14 15:42:38',NULL,NULL,'{name},{storeName}'),(40,'Forgot password link','Forgot password link','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                \n		We\'ve received a request to change your login password. To proceed, please Click The Below Link for reset your password.<br><br>\n		 <b><a href= {link} style=\"display: block;\n    text-decoration: none;\n    padding: 16px 40px;\n    background-color: #027600;\n    border-radius: 6px;\n    color: #FFFFFF;\n    font-size: 16px;\n    line-height: 20px;\n    width: fit-content;\n    margin: auto;\">Click Here</a></b><br></p>',1,'2024-05-18 10:16:13','2024-08-03 04:06:39',NULL,NULL,'{name},{link}'),(41,'change_user_login_email','Change User Login Email','\n            <h1\n                style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We\'ve received a request to change your login Email Id. To proceed, please Enter the below OTP:<br><br>\n                <b>{xxxxxx}</b></p> <br>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 26px 0;\">\n                If you didn’t mean to make this request, just ignore the email, and we’ll forget this ever happened.\n                </p>',1,'2024-05-23 06:17:32','2024-09-27 09:57:56',NULL,NULL,'{name},{xxxxxx}'),(42,'Vendor Email Verification','Your Seller Registration has been activated by {siteName} Admin ','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1><br><br>\n                \n<p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We\'re glad to inform you that your Seller Registration has been activated by Admin.<br>\n                \n                Now, as part of the Seller Registration formality, you need to verify your Seller Credentials.<br>\n                \n                On hitting the \'Click Here\' option below, you will get a form, \n                where you need to provide your credentials (Email Id and Password) that you had provided while signing up as a Seller.<br><br>\n                \n                <b><a href= {link} style=\"display: block;\n    text-decoration: none;\n    padding: 16px 40px;\n    background-color: #027600;\n    border-radius: 6px;\n    color: #FFFFFF;\n    font-size: 16px;\n    line-height: 20px;\n    width: fit-content;\n    margin: auto;\">Click Here</a></b><br>\n    On providing correct credentials, your Verification process will be complete and you can start with your Seller On-boarding Process on your Seller Panel,\n     by logging into it.<br> Wish you the best at <b>{storeName}</b>.<br><br></p>\n\n ',1,'2024-05-29 13:43:54','2024-09-16 11:18:19',NULL,NULL,'{name},{link}'),(43,'Admin Product Reject','Product Rejected','<h3 style=\" font-weight: bold; font-size: 20px; color: #131921; margin-bottom: 16px; font-family: \'Roboto\',\n                                        sans-serif; text-align: left; line-height: 24px; \"> Hello {name}, </h3>\n                                    <p style=\" color: #222222; text-align: left; font-size: 16px; font-weight: normal; line-height: 27px; font-family:\n                                        \'Roboto\', sans-serif; text-align: left; padding-bottom: 32px; \"> We regret to inform you that your Product\n                                        request has been rejected for the following reason: </p>\n                                    <p style=\" font-size: 18px; font-weight:line-height: 22px; \">\n                                    <ul>\n                                        <li>{XXXXXX}</li>\n                                    </ul>\n                                    </p>\n                                    <p style=\" color: #222222; text-align: left; font-size: 16px; font-weight: normal; line-height: 27px; font-family:\n                                        \'Roboto\', sans-serif; text-align: left; padding-bottom: 32px; \"> If you didn\'t request this change, please \n\n                                        contact our support team immediately. </p>\n                                    <p style=\"border-bottom: 1px solid #f0f0f0\"></p>',1,'2024-05-31 07:05:51','2024-05-31 07:05:51',NULL,NULL,'{XXXXXX},{name}'),(44,'Vendor Onboard Rejection','Rejection of Seller Onboarding Request','<h1 style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\"> Hi {name},\n            </h1>\n            <p style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\"> We regret to\n                inform you that your onboarding request as a Seller at {appName} has been rejected for the following reasons.\n            </p>\n            <div style=\"padding: 16px; background-color: #F9F9FC;margin: 0 0 24px 0;\">\n                <h2 style=\"color: #1F2328;font-size: 17px;line-height: 24px;font-weight: 600;margin:0 0 8px 0;\"> Reasons:\n                </h2>\n                <p style=\"font-size: 14px;line-height: 18px;color: #262626;font-weight: normal; margin: 0;\"> {comments} </p>\n            </div>',1,'2024-05-31 14:12:53','2024-05-31 14:12:53',NULL,NULL,NULL),(45,'change_mail','Change your mail with a one-time password.','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},<br>\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We have received a request to change the email address associated with your account. To ensure the security of your account, we require verification.\n                Please find below the One-Time Password (OTP) necessary to proceed with the email address change: <br><br>\n                <b>OTP: {otp}</b> (Please do not share this OTP with anyone)<br> </p>\n                <p style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 26px 0;\">\n		If you did not make this request, just ignore the email and we will forget this ever happened.\n                </p>',1,'2024-06-03 12:42:14','2024-06-03 12:42:14',NULL,NULL,'{name},{otp},{companyName}'),(46,'Vendor Notification for Product Inventory Stock Closed','Product Inventory Stock Closed','<h1 style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n                <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                <b>DETAILED REQUIREMENTS:</b><br>{userRequirements} <br><br>\n                <b>FullName :</b> {FullName}<br>\n                <b>Email ID :</b> {EmailId}<br>\n                <b>Attachments :</b> attachments includes<br>\n                <br><br>\n                </p>',NULL,'2026-02-06 13:10:24','2026-02-06 13:10:24',NULL,NULL,'{name},{productName}'),(47,'Vendor Verification Success','Congratulations ! Your Seller Onboarding Request is approved !!','<h2><strong>Hi {name},</strong></h2><p>Congratulations ! Your Seller Onboarding request submitted to {companyName} marketplace is approved and you can now start building your catalog and can explore all the features of Seller Panel.</p><p>Happy Selling !!</p><p>Regards,</p><h3><strong>{companyName} Team</strong></h3><p><a href=\"style=/&quot;font-size:\">{vendorUrl}&nbsp;</a></p>',1,'2024-07-18 15:09:46','2024-09-11 07:43:10',NULL,NULL,'{name},{companyName},{vendorUrl}'),(48,'vendor_contact','Request from store customer','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1>\n            <p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                <b>DETAILED REQUIREMENTS:</b><br>{userRequirements} <br><br>\n                <b>FullName :</b> {FullName}<br>\n                <b>Email ID :</b> {EmailId}<br>\n                <b>Attachments :</b> attachments includes<br>\n                <br><br>\n                </p>',1,'2024-07-11 16:50:20','2024-07-15 06:07:03',NULL,NULL,'{name},{productName}'),(49,'Customer Backorder Content','Order Confirmation: Back Order for {productName}','<h1\r\n                                                                                        style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                                                                                        Hi {name},</h1>\r\n                                                                                    <p\r\n                                                                                        style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\r\n                                                                                        Thank you for your order! We want to let you know that the Product - <b>{productName}</b> is currently out of stock and has been placed on back order.<br><br>We appreciate your patience as we work to fulfill your order. You will receive a notification once the product is back in stock and ready for shipment.<br><br></p>',1,'2024-09-20 11:47:26','2024-10-07 11:42:08',NULL,NULL,'{name},{productName}'),(50,'Admin Backorder Content','Order Notification: Back Order for {productName}','<h1\r\n                                                                                        style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                                                                                        Hi {name},</h1>\r\n                                                                                    <p\r\n                                                                                        style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 40px 0;\">\r\n                                                                                        This is to inform you that the customer  has placed an order for {productName}, which is currently out of stock. The order has been placed on back order.<br>\r\n                                                                                        <b>Order Id:</b> {orderId}<b><br>Customer Name:</b> {customerName}<br><b>Customer Mail:</b> {customerMail}<br><b>Quantity:</b> {quantity}<br><br> Please prepare to fulfill the order once the product is back in stock.<br> \r\n\r\nThank you for your attention!</p>',NULL,'2024-09-20 11:47:26','2024-09-20 11:47:26',NULL,NULL,'{name},{orderId},{customerMail},{quantity},{productName}'),(51,'Product Create Admin Intimation','New Product Created by {sellerName}: {productName}','<h1\r\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                Hi {name},\r\n                </h1>\r\n            <p\r\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\r\n                We would like to inform you that <b>{sellerName}</b> has just created a new product listing, <b>{productName}</b>, on the platform.<br><br>\r\n		Please review the product details and ensure it meets all the necessary criteria for approval. If any discrepancies or issues are found during the review, kindly reach out to the seller for 	corrections or updates.<br><br>\r\n		Let us ensure that the product is ready to go live at the earliest.<br>\r\n                </p>\r\n                \r\n',1,'2024-10-08 13:58:05','2024-10-08 13:58:05',NULL,NULL,'{name},{sellerName},{productName}'),(52,'Seller KYC Submitted Intimation to Admin','KYC Submission Notification','<h1\r\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                Hi {name},\r\n                </h1><br>\r\n                \r\n<p\r\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\r\n                A seller has submitted their KYC documentation for verification.\r\n                Please review the submitted documents at your earliest convenience.<br><br>\r\n                <b>Seller Details:</b><br><br>\r\n<b>Seller Name :</b> {selerName}<br>\r\n<b>Seller Id :</b> {sellerId}<br>\r\n<b>Submission Date :</b> {submissionDate}<br><br>\r\n</p>',1,'2024-10-16 13:45:15','2024-10-16 13:45:15',NULL,NULL,'{selerName},{sellerId},{submissionDate}'),(53,'Seller KYC Submitted Intimation to Seller','KYC Submitted Intimation to Seller ','<h1\r\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                Hi {name},\r\n                </h1><br>\r\n                \r\n<p\r\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\r\n                Thank you for submitting your KYC documentation. Your documents are currently under review. We will notify you once the verification process is complete.<br><br>\r\n                If you have any questions, feel free to reach out to our support team.<br><br>\r\n</p>\r\n',1,'2024-10-16 13:45:15','2024-10-16 13:45:15',NULL,NULL,'{name}'),(54,'Seller KYC Approval Email','KYC Status Update','<h1\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\n                Hi {name},\n                </h1><br>\n                \n<p\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\n                We are pleased to inform you that your KYC documentation has been successfully approved. You can now enjoy full access to all features of your seller account.<br><br>\n                Thank you for your cooperation. If you have any further questions or need assistance, please do not hesitate to reach out.<br><br>\n</p>',1,'2024-10-16 13:45:39','2024-10-16 13:45:39',NULL,NULL,'{name}'),(55,'Seller KYC Reject Email','Important: KYC Rejection Update','<h1 style=\"font-size: 24px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\"> Hi {name},\r\n            </h1>\r\n            <p style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\"> \r\n            We regret to inform you that your KYC documentation has been rejected. Please review the following reasons for the rejection:<br><br>\r\n            </p>\r\n            <div style=\"padding: 16px; background-color: #F9F9FC;margin: 0 0 24px 0;\">\r\n                <p style=\"font-size: 14px;line-height: 18px;color: #262626;font-weight: normal; margin: 0;\"> {comments} </p><br>\r\n                <p style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\r\n                To proceed, kindly resubmit the necessary documents for verification. If you have any questions or need assistance, feel free to contact our support team.\r\n                </p>\r\n            </div>',1,'2024-10-16 13:45:39','2024-10-18 14:55:47',NULL,NULL,'{name},{comments}'),(56,'Seller sign-up','You just signed-up as a Seller with {siteName}','<h1\r\n        style=\"font-size: 20px; line-height: 29px; font-weight: 600;margin: 0 0 12px 0;color:#1F2328;\">\r\n                Hi {name},\r\n                </h1><br>\r\n                \r\n<p\r\n                style=\"font-size: 16px; line-height: 24px;color: #1F2328;font-weight: normal;margin: 0 0 24px 0;\">\r\n                Thank you for expressing your interest and signing up as a Seller with <b>{siteName}.</b><br><br> \r\n               Your seller registration is with the Admin for approval. Once approved by the Admin,\r\n you will be able to login to the seller Panel.<br><br>\r\n                If you have any questions, feel free to reach out to our support team.<br><br>\r\n</p>',1,'2024-10-22 07:48:21','2024-10-22 07:48:21',NULL,NULL,'{name},{siteName}'),(57,'Product Cancellation by Buyer','Order Cancellation Request from Buyer','Dear {sellerName},<br/><br/>\n                <p style=\"margin-bottom:.5em; margin: 0 0 10px 0; text-indent: 50px\">The buyer has requested to cancel the ordered product: <strong>{productName}</strong>. Please review and respond to the cancellation request.</p>',NULL,'2026-02-06 13:10:24','2026-02-06 13:10:24',NULL,NULL,'{sellerName},{productName}'),(58,'Support Request','Support Ticket Notification','Dear Admin,<br/><br/>\n                <p style=\"margin-bottom: .5em; margin: 0 0 10px 0; text-indent: 50px\">\n                <strong>{name}</strong> has raised a new support ticket regarding: <strong>{subject}</strong>.\n                </p>\n\n                <p style=\"margin-bottom: .5em; margin: 0 0 10px 0; text-indent: 50px\">\n                Please review the ticket details and take appropriate action.\n                </p>',NULL,'2026-02-06 13:10:24','2026-02-06 13:10:24',NULL,NULL,'{name},{subject}'),(59,'Ticket Closed','Ticket Closed by Admin','Dear {name},<br/><br/>\n                <p style=\"margin-bottom: .5em; margin: 0 0 10px 0; text-indent: 50px\">\n                  The ticket regarding  <strong>{subject}</strong> has been closed by Admin . Please find the details in Your support section.\n                </p>',NULL,'2026-02-06 13:10:25','2026-02-06 13:10:25',NULL,NULL,'{name},{subject}');
/*!40000 ALTER TABLE `email_template` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `export_log`
--

DROP TABLE IF EXISTS `export_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `export_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `module` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_available` int DEFAULT NULL,
  `created_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `reference_id` int DEFAULT NULL,
  `reference_type` int DEFAULT NULL,
  `product_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `export_id` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
